mapper.select:
SELECT  FROM sys_auth_log

ORDER BY id DESC
LIMIT #{offset}, #{size}

SELECT mac AS name, COUNT(1) AS value
FROM sys_auth_log

    result <> 1
    AND mac IS NOT NULL AND mac <> ''
    AND create_time >= #{startTime}
    AND create_time <= #{endTime}

GROUP BY mac
ORDER BY value DESC
LIMIT #{limit}

SELECT COALESCE(NULLIF(username,''), NULLIF(phone,''), '(未知)') AS name, COUNT(1) AS value
FROM sys_auth_log

    result <> 1
    AND create_time >= #{startTime}
    AND create_time <= #{endTime}

GROUP BY name
ORDER BY value DESC
LIMIT #{limit}

SELECT COALESCE(NULLIF(nas_name,''), NULLIF(nas_ip,''), '(未知)') AS name, COUNT(1) AS value
FROM sys_auth_log

    result <> 1
    AND create_time >= #{startTime}
    AND create_time <= #{endTime}

GROUP BY name
ORDER BY value DESC
LIMIT #{limit}

SELECT l.id AS id, l.auth_type AS authType, l.username AS username, l.phone AS phone, l.mac AS mac, l.ip AS ip, l.nas_ip AS nasIp, l.ssid AS ssid, l.nas_name AS nasName, l.result AS result, l.message AS message, l.create_time AS createTime, u.real_name AS respName, u.username AS respUsername, u.dept AS respDept FROM sys_auth_log l LEFT JOIN sys_user u ON (l.username IS NOT NULL AND l.username <> '' AND u.username = l.username) OR (l.phone IS NOT NULL AND l.phone <> '' AND u.phone_blind = l.phone)
AND l.auth_type = #{authType} AND l.result = #{result} AND (l.username LIKE CONCAT('%',#{username},'%') OR l.phone LIKE CONCAT('%',#{username},'%')) AND l.mac LIKE CONCAT('%',#{mac},'%') AND l.ip LIKE CONCAT('%',#{ip},'%') AND l.create_time >= #{startTime} AND l.create_time <= #{endTime}
ORDER BY l.id DESC LIMIT #{limit}
